import XCTest

@testable import PetstoreClient

final class HeaderSelectorTests: XCTestCase {

  func testIsJSONMIME() {
    let hs = HeaderSelector()

    let testCases: [(String, Bool)] = [
      ("application/json", true),
      ("application/json; charset=utf-8", true),
      ("application/vnd.api+json", true),
      ("application/xml", false),
      ("text/plain", false),
      ("", false),
      ("application/octet-stream", false),
      ("application/hal+json", true),
    ]

    for (input, expected) in testCases {
      XCTAssertEqual(hs.isJSONMIME(input), expected, "IsJSONMIME(\(input)) should be \(expected)")
    }
  }

  func testSelectHeadersWithSingleAccept() {
    let hs = HeaderSelector()
    let headers = hs.selectHeaders(
      accept: ["application/json"], contentType: "application/json", isMultipart: false)

    XCTAssertEqual(headers["Accept"], "application/json")
    XCTAssertEqual(headers["Content-Type"], "application/json")
  }

  func testSelectHeadersWithMultipleAccepts() {
    let hs = HeaderSelector()
    let headers = hs.selectHeaders(
      accept: ["application/json", "application/xml"], contentType: "application/json",
      isMultipart: false)

    let accept = headers["Accept"] ?? ""
    XCTAssertTrue(accept.contains("application/json"))
  }

  func testSelectHeadersWithEmptyAccepts() {
    let hs = HeaderSelector()
    let headers = hs.selectHeaders(accept: [], contentType: "application/json", isMultipart: false)

    XCTAssertNil(headers["Accept"])
  }

  func testSelectHeadersMultipartOmitsContentType() {
    let hs = HeaderSelector()
    let headers = hs.selectHeaders(
      accept: ["application/json"], contentType: "multipart/form-data", isMultipart: true)

    XCTAssertNil(headers["Content-Type"])
  }

  func testSelectHeadersDefaultContentType() {
    let hs = HeaderSelector()
    let headers = hs.selectHeaders(
      accept: ["application/json"], contentType: "", isMultipart: false)

    XCTAssertEqual(headers["Content-Type"], "application/json")
  }

  func testQualityWeighting() {
    let hs = HeaderSelector()
    let headers = hs.selectHeaders(
      accept: ["application/json", "application/xml", "text/plain"],
      contentType: "application/json",
      isMultipart: false
    )

    let accept = headers["Accept"] ?? ""
    XCTAssertFalse(accept.isEmpty)

    // application/json should appear first (highest priority)
    let jsonIdx = accept.range(of: "application/json")
    let xmlIdx = accept.range(of: "application/xml")
    XCTAssertNotNil(jsonIdx)
    XCTAssertNotNil(xmlIdx)
    if let jsonIdx = jsonIdx, let xmlIdx = xmlIdx {
      XCTAssertTrue(jsonIdx.lowerBound < xmlIdx.lowerBound)
    }
  }

  func testSelectHeadersWithVendorJSON() {
    let hs = HeaderSelector()
    let headers = hs.selectHeaders(
      accept: ["application/vnd.api+json", "application/xml"],
      contentType: "application/json",
      isMultipart: false
    )

    let accept = headers["Accept"] ?? ""
    XCTAssertTrue(accept.contains("application/vnd.api+json"))
  }
